import { Player, PlayerChoice, PlayerEvent } from './common';

const escapeRegExp = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function compactHermitOutcome(message: string, targetName?: string): string | undefined {
    const match = message.match(/^gave Hermit Card to .+? and (.+)$/);
    if (!match) return undefined;

    let outcome = match[1];
    if (targetName) {
        const target = escapeRegExp(targetName);
        outcome = outcome.replace(new RegExp(`^${target} `), '');
        outcome = outcome.replace(new RegExp(`had no effect on ${target}\\.?$`), 'no effect.');
        outcome = outcome.replace(new RegExp(` (?:to|from|on) ${target}(\\.)?$`), '$1');
    }
    return outcome;
}

export function eventDialogText(players: Player[], playerEvent: PlayerEvent): string | undefined {
    const playerName = players.find(player => player.user.id === playerEvent.playerId)?.user.userName ?? 'A player';
    if (playerEvent.revealedCard) return `${playerName} revealed their character.`;

    const playerChoice = playerEvent as unknown as Partial<PlayerChoice>;
    const choice = playerChoice.choice;
    const cardName = choice?.card.name;
    if (cardName?.startsWith("Hermit's ")) {
        const targetName = players.find(player => player.user.id === playerChoice.result)?.user.userName;
        const cardLabel = cardName.replace("Hermit's ", '').replace(/\s+\d+$/, '');
        const outcome = playerEvent.message ? compactHermitOutcome(playerEvent.message, targetName) : undefined;
        return `${playerName}: ${cardLabel}${targetName ? ` → ${targetName}` : ''}${outcome ? ` — ${outcome}` : '.'}`;
    }

    if (playerEvent.message) return `${playerName} ${playerEvent.message}`;
    switch (playerEvent.actionType) {
        case 'PlayerAttack':
            return `${playerName} is making an attack.`;
        case 'PlayerChoice':
            return `${playerName} is making a choice.`;
        case 'PlayerDeath':
            return `${playerName} died.`;
        case 'PlayerMove':
            return `${playerName} is moving.`;
        case 'PlayerDraw':
            return `${playerName} drew a card.`;
        case 'PlayerAbility':
            return `${playerName} is using an ability.`;
        case 'PlayerEndTurn':
            return `${playerName} ended their turn.`;
        default:
            return undefined;
    }
}
