import { useAppDispatch, useAppSelector } from '../store/hooks';
import { ChoiceType, ConnectionState, Decks, PlayerActionType, PlayerChoice, Target, UserDetails } from '../helpers/common';
import Grid from '@mui/material/Grid';
import Button from '@mui/material/Button';
import { PeerState } from '../store/peer/peerTypes';
import { updateGameState, useAbility } from '../store/connection/connectionActions';
import { initialState } from '../store/connection/connectionReducer';
import { useNavigate } from 'react-router';
import * as React from 'react';
import Box from '@mui/material/Box';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import List from '@mui/material/List';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemText from '@mui/material/ListItemText';
import { RandomRange } from '../helpers/common';
import { GiSemiClosedEye, GiExitDoor, GiHourglass, GiDrippingSword, GiMagicSwirl, GiWalkingBoot, GiBandit, GiHammerBreak } from 'react-icons/gi';

const gameControlButtonSx = {
    marginRight: 2,
    minHeight: '54px',
    paddingX: '24px',
    fontSize: '1.3125rem'
};

function PlayerGui({ handleChoice = (playerChoice) => playerChoice, handleAttack = (targets) => targets, handleMove = () => { }, handleEndTurn = () => { }, canAttack = false, onQuit, compact = false }:
    {
        handleAttack: (targets?: UserDetails[] | undefined) => void,
        handleChoice: (playerChoice: PlayerChoice) => void,
        handleMove: () => void,
        handleEndTurn: () => void,
        canAttack?: boolean,
        onQuit?: () => void,
        compact?: boolean
    }) {
    const connection = useAppSelector((state) => state.connection) as ConnectionState;
    const peer = useAppSelector((state) => state.peer) as PeerState;
    const player = connection.gameState.lobby.playerList.filter(x => x.user.id === peer.id)[0];
    const [showGui, setShowGui] = React.useState<boolean>(false);
    const [abilityDialogOpen, setAbilityDialogOpen] = React.useState(false);
    const lastLocalTurn = React.useRef<string | undefined>(undefined);
    const dispatch = useAppDispatch();
    const navigate = useNavigate();
    const pendingLoot = connection.gameState.pendingLoot;

    React.useEffect(() => {
        const localTurnActive = connection.gameState.started
            && !connection.gameState.gameEnded
            && !connection.gameState.disconnectedPlayer
            && connection.gameState.currentPlayer === peer.id
            && !player?.piece.dead;
        if (!localTurnActive) {
            lastLocalTurn.current = undefined;
            return;
        }
        if (lastLocalTurn.current === connection.gameState.currentPlayer) return;
        lastLocalTurn.current = connection.gameState.currentPlayer;
        setShowGui(true);
    }, [connection.gameState.currentPlayer, connection.gameState.disconnectedPlayer, connection.gameState.gameEnded, connection.gameState.started, peer.id, player?.piece.dead]);

    const handleReveal = () => {
        handleChoice({ choice: { type: ChoiceType.reveal, card: { ...player.piece.character, drawDeck: Decks.characters }, target: peer.id! }, playerId: peer.id!, actionType: PlayerActionType.playerChoice });
    }

    const handleAbility = () => {
        const targetAbilities = ['chainOfForbiddenCurse', 'lightning', 'dynamiteNurse', 'demolish', 'murderRay', 'graveDigger'];
        if (targetAbilities.includes(player.piece.character.ability?.name ?? '')) {
            setAbilityDialogOpen(true);
            return;
        }
        dispatch(useAbility({ playerId: peer.id!, actionType: PlayerActionType.playerAbility }));
    }

    const useAbilityOnTarget = (targetId: string) => {
        const ability = player.piece.character.ability!;
        const roll = ability.name === 'lightning' ? RandomRange(1, 6) : ability.name === 'demolish' ? RandomRange(1, 4) : undefined;
        setAbilityDialogOpen(false);
        dispatch(useAbility({ playerId: peer.id!, actionType: PlayerActionType.playerAbility, targetId, roll }));
    }

    const abilityTargets = connection.gameState.lobby.playerList.filter(candidate => {
        if (candidate.piece.dead) return false;
        if (player.piece.character.ability?.name === 'murderRay') {
            const gateIndex = connection.gameState.lobby.decks[Decks.areas].cards.findIndex(card => card.name === 'Underworld Gate');
            return candidate.piece.position === gateIndex;
        }
        return candidate.user.id !== peer.id;
    });

    const discardItems = Object.values(connection.gameState.lobby.discard).flatMap(deck => deck.cards);

    const handleQuit = () => {
        if (onQuit) {
            onQuit();
            return;
        }
        if (connection.peerId === connection.gameState.hostId) {
            navigate('/');
            return;
        }
        dispatch(updateGameState(initialState.gameState));
        navigate('/');
    }

    const controlButtonSx = compact ? { ...gameControlButtonSx, marginRight: 0, marginBottom: 1, minWidth: '54px', paddingX: 0 } : gameControlButtonSx;
    const controlIconStyle = compact ? undefined : { marginRight: 16, marginTop: '-4px' };

    return <Grid sx={{
        bottom: compact ? 0 : 16,
        left: compact ? undefined : -16,
        right: compact ? 0 : undefined,
        position: 'absolute',
        zIndex: 1200,
        paddingTop: compact ? 1.5 : 5,
        paddingLeft: compact ? 1.5 : 5,
        paddingRight: compact ? 1.5 : 0,
        paddingBottom: compact ? 0.5 : 0
    }}
        display='flex' spacing={'2px'} justifyContent='center' alignItems='center'>
        {
            <Box sx={compact ? { display: 'flex', flexDirection: 'column', alignItems: 'flex-start' } : undefined}>
                {
                    showGui ?
                        <React.Fragment>

                            {
                                pendingLoot?.killerId === peer.id ? <React.Fragment>
                                    <Button aria-label='Take equipment' sx={controlButtonSx} variant='contained' onClick={() => { setAbilityDialogOpen(true); }}><GiBandit style={controlIconStyle} />{compact ? undefined : 'Take equipment'}</Button>
                                    <Button aria-label='Discard equipment' sx={controlButtonSx} variant='contained' onClick={() => { dispatch(useAbility({ playerId: peer.id!, actionType: PlayerActionType.playerAbility, itemName: '' })); }}><GiHammerBreak style={controlIconStyle} />{compact ? undefined : 'Discard equipment'}</Button>
                                </React.Fragment> :
                                    connection.gameState.currentPlayer === peer.id && !connection.gameState.pendingCounterattack ?
                                        <React.Fragment>
                                            {player.piece.moved ? undefined :
                                                <Button aria-label='Move' sx={controlButtonSx} variant='contained' onClick={() => { handleMove(); }}><GiWalkingBoot style={controlIconStyle} />{compact ? undefined : 'Move'}</Button>}
                                            {player.piece.attacked || !canAttack ? undefined : player.piece.moved ?
                                                <Button aria-label='Attack' sx={controlButtonSx} variant='contained' onClick={() => { handleAttack(); }}><GiDrippingSword style={controlIconStyle} />{compact ? undefined : 'Attack'}</Button> : undefined}
                                            {player.piece.revealed ? undefined :
                                                <Button aria-label='Reveal Character' sx={controlButtonSx} variant='contained' onClick={() => { handleReveal(); }}><GiSemiClosedEye style={controlIconStyle} />{compact ? undefined : ' Reveal Character'}</Button>}
                                            {!player.piece.revealed || player.piece.abilityUsed || player.piece.character.ability?.target === Target.attacker || !player.piece.character.ability || player.piece.character.ability.passive ? undefined :
                                                <Button aria-label='Use Ability' sx={controlButtonSx} variant='contained' onClick={() => { handleAbility(); }}><GiMagicSwirl style={controlIconStyle} />{compact ? undefined : ' Use Ability'}</Button>}
                                            {player.piece.moved && !player.piece.attacked ? <Button aria-label='End Turn' sx={controlButtonSx} variant='contained' color='info' onClick={() => { handleEndTurn(); }}><GiHourglass style={controlIconStyle} />{compact ? undefined : 'End Turn'}</Button> : undefined}
                                        </React.Fragment> : undefined
                            }
                        </React.Fragment> : undefined
                }
                <Button aria-label='Quit' sx={controlButtonSx} onClick={() => handleQuit()} color='error' variant='contained'><GiExitDoor style={controlIconStyle} />{compact ? undefined : ' Quit'}</Button>
            </Box>
        }
        <Dialog open={abilityDialogOpen} onClose={() => setAbilityDialogOpen(false)}>
            <DialogTitle>Choose {player?.piece.character.ability?.name === 'graveDigger' ? 'equipment' : 'a target'} for {player?.piece.character.ability?.name}</DialogTitle>
            <DialogContent>
                <List>
                    {pendingLoot?.killerId === peer.id
                        ? pendingLoot?.items.map(item => <ListItemButton key={`${item.drawDeck}-${item.name}`} onClick={() => {
                            setAbilityDialogOpen(false);
                            dispatch(useAbility({ playerId: peer.id!, actionType: PlayerActionType.playerAbility, itemName: item.name }));
                        }}><ListItemText primary={item.name} /></ListItemButton>)
                        : player?.piece.character.ability?.name === 'graveDigger'
                            ? discardItems.filter(item => item.isItem).map(item => <ListItemButton key={`${item.drawDeck}-${item.name}`} onClick={() => {
                                setAbilityDialogOpen(false);
                                dispatch(useAbility({ playerId: peer.id!, actionType: PlayerActionType.playerAbility, itemName: item.name }));
                            }}><ListItemText primary={item.name} /></ListItemButton>)
                            : abilityTargets.map(target => <ListItemButton key={target.user.id} onClick={() => useAbilityOnTarget(target.user.id)}>
                                <ListItemText primary={target.user.userName} />
                            </ListItemButton>)}
                </List>
            </DialogContent>
        </Dialog>
    </Grid>;
}

export default PlayerGui;
