import { CharacterCategory, ChoiceType, GameState, Player, PlayerAbility, PlayerAttack, PlayerChoice, PlayerEndTurn, PlayerMove, PlayerActionType, Target, rollDice } from '../../helpers/common';
import { attackModifierFor, attackRangeFor, hasMachineGun, hasSword, usesSingleDieAttack } from '../../helpers/cardAction';

export const DEFAULT_BOT_THINK_TIME_MS = 750;

export type BotAction =
    | { kind: 'move', event: PlayerMove }
    | { kind: 'attack', event: PlayerAttack }
    | { kind: 'ability', event: PlayerAbility }
    | { kind: 'endTurn', event: PlayerEndTurn };

export const isBot = (player: Player | undefined) => Boolean(player?.user.isBot);

const playerFor = (gameState: GameState, id: string) => gameState.lobby.playerList.find(player => player.user.id === id);
const isAlly = (bot: Player, candidate: Player) =>
    bot.piece.character.category !== CharacterCategory.neutral
    && candidate.piece.character.category === bot.piece.character.category;

/** Bots do not infer factions from hidden game state. They need evidence. */
function isKnownHostile(gameState: GameState, bot: Player, candidate: Player) {
    if (candidate.piece.dead || candidate.user.id === bot.user.id) return false;
    if (gameState.botHostilities?.[bot.user.id]?.includes(candidate.user.id)) return true;
    if (candidate.piece.revealed) {
        return candidate.piece.character.category !== bot.piece.character.category;
    }
    const knownFaction = gameState.botFactionKnowledge?.[bot.user.id]?.[candidate.user.id];
    return knownFaction !== undefined && knownFaction !== bot.piece.character.category;
}

function enemyTarget(gameState: GameState, bot: Player, candidates = gameState.lobby.playerList): Player | undefined {
    return candidates.filter(candidate => !candidate.piece.dead && candidate.user.id !== bot.user.id)
        .sort((left, right) => {
            const leftScore = isAlly(bot, left) ? -100 : (left.piece.character.category === CharacterCategory.neutral ? 1 : 2);
            const rightScore = isAlly(bot, right) ? -100 : (right.piece.character.category === CharacterCategory.neutral ? 1 : 2);
            return rightScore - leftScore || right.piece.damage - left.piece.damage;
        })[0];
}

function knownHostileTarget(gameState: GameState, bot: Player, candidates = gameState.lobby.playerList): Player | undefined {
    return enemyTarget(gameState, bot, candidates.filter(candidate => isKnownHostile(gameState, bot, candidate)));
}

function isKnownAlly(gameState: GameState, bot: Player, candidate: Player): boolean {
    if (bot.piece.character.category === CharacterCategory.neutral) return false;
    if (candidate.piece.revealed && candidate.piece.character.category === bot.piece.character.category) return true;
    return gameState.botFactionKnowledge?.[bot.user.id]?.[candidate.user.id] === bot.piece.character.category;
}

/**
 * Bots begin by requiring evidence of hostility. After five full rounds they
 * may press a wounded unknown player; one round later they will challenge any
 * unknown player in range, but never a teammate whose faction they know.
 */
function escalatingTarget(gameState: GameState, bot: Player, candidates: Player[]): Player | undefined {
    const livingPlayerCount = gameState.lobby.playerList.filter(player => !player.piece.dead).length;
    const completedRounds = Math.floor((gameState.completedTurns ?? 0) / Math.max(1, livingPlayerCount));
    if (completedRounds <= 5) return undefined;

    const unknownCandidates = candidates.filter(candidate =>
        !candidate.piece.dead
        && candidate.user.id !== bot.user.id
        && !isKnownAlly(gameState, bot, candidate)
        && !isKnownHostile(gameState, bot, candidate));
    if (completedRounds === 6) {
        return unknownCandidates.filter(candidate => candidate.piece.damage > 0)
            .sort((left, right) => right.piece.damage - left.piece.damage)[0];
    }
    return unknownCandidates.sort((left, right) => right.piece.damage - left.piece.damage)[0];
}

/** Choose without inspecting a hidden character. Used only when a card cannot be declined. */
function randomOtherLivingPlayer(gameState: GameState, bot: Player, candidates = gameState.lobby.playerList): Player | undefined {
    const eligibleCandidates = candidates.filter(candidate =>
        !candidate.piece.dead && candidate.user.id !== bot.user.id);
    return eligibleCandidates[Math.floor(Math.random() * eligibleCandidates.length)];
}

function isOffensiveTargetCard(card: PlayerChoice['choice']['card']): boolean {
    if ((card.damage ?? 0) > 0 && [Target.player, Target.both].includes(card.damageTarget ?? Target.player)) {
        return true;
    }
    if (card.name === 'Spiritual Doll') return true;
    return [
        "Hermit's Anger 1", "Hermit's Anger 2",
        "Hermit's Blackmail 1", "Hermit's Blackmail 2",
        "Hermit's Bully", "Hermit's Exorcism",
        "Hermit's Greed 1", "Hermit's Greed 2",
        "Hermit's Slap 1", "Hermit's Slap 2",
        "Hermit's Spell", "Hermit's Tough Lesson of Love"
    ].includes(card.name);
}

function lowestDamageAlly(gameState: GameState, bot: Player): Player | undefined {
    return gameState.lobby.playerList.filter(candidate => !candidate.piece.dead && candidate.user.id !== bot.user.id
        && isAlly(bot, candidate) && candidate.piece.damage > 0)
        .sort((left, right) => right.piece.damage - left.piece.damage)[0];
}

function chooseMove(bot: Player): PlayerMove {
    // Movement follows the same dice result as a human turn; strategy begins
    // after arriving (card, target, healing, or attack decisions).
    return { playerId: bot.user.id, actionType: PlayerActionType.playerMove, moveRoll: rollDice([6, 4]) };
}

function abilityAction(gameState: GameState, bot: Player): PlayerAbility | undefined {
    const ability = bot.piece.character.ability;
    if (!ability || ability.automatic || bot.piece.abilityUsed || bot.piece.abilityBlocked || bot.piece.moved) return undefined;

    if (['mothersLove', 'stigmata'].includes(ability.name) && bot.piece.damage > 0) {
        return { playerId: bot.user.id, actionType: PlayerActionType.playerAbility };
    }
    if (ability.name === 'graveDigger') {
        const item = Object.values(gameState.lobby.discard).flatMap(deck => deck.cards).find(card => card.isItem);
        return item ? { playerId: bot.user.id, actionType: PlayerActionType.playerAbility, itemName: item.name } : undefined;
    }
    if (ability.target === Target.player) {
        const gateIndex = gameState.lobby.decks.areas.cards.findIndex(card => card.name === 'Underworld Gate');
        const target = ability.name === 'murderRay'
            ? knownHostileTarget(gameState, bot, gameState.lobby.playerList.filter(player => player.piece.position === gateIndex))
            : knownHostileTarget(gameState, bot);
        if (target) return {
            playerId: bot.user.id,
            actionType: PlayerActionType.playerAbility,
            targetId: target.user.id,
            roll: ability.name === 'lightning' ? 6 : ability.name === 'demolish' ? 4 : undefined
        };
    }
    return undefined;
}

/** Returns one legal action. The caller schedules each returned action separately. */
export function chooseBotAction(gameState: GameState): BotAction | undefined {
    if (gameState.gameEnded) return undefined;
    if (gameState.pendingLoot) {
        const killer = playerFor(gameState, gameState.pendingLoot.killerId);
        if (isBot(killer)) {
            return { kind: 'ability', event: { playerId: killer!.user.id, actionType: PlayerActionType.playerAbility, itemName: gameState.pendingLoot.items[0]?.name } };
        }
        return undefined;
    }
    if (gameState.pendingCounterattack) {
        const responder = playerFor(gameState, gameState.pendingCounterattack.responderId);
        const attacker = playerFor(gameState, gameState.pendingCounterattack.attackerId);
        if (isBot(responder) && attacker) {
            return {
                kind: 'attack',
                event: {
                    playerId: responder!.user.id,
                    actionType: PlayerActionType.playerAttack,
                    targets: [attacker.user],
                    damageRoll: usesSingleDieAttack(responder!) ? [4] : [6, 1],
                    modifiers: attackModifierFor(responder!)
                }
            };
        }
        return undefined;
    }

    const bot = playerFor(gameState, gameState.currentPlayer);
    if (!isBot(bot) || bot!.piece.dead) return undefined;
    const ability = abilityAction(gameState, bot!);
    if (ability) return { kind: 'ability', event: ability };
    if (!bot!.piece.moved) return { kind: 'move', event: chooseMove(bot!) };
    if (!bot!.piece.attacked) {
        const targetsInRange = attackRangeFor(gameState, bot!);
        // The Cursed Sword requires an attack whenever a legal target is in
        // range, even before the bot has enough information to identify an enemy.
        const target = knownHostileTarget(gameState, bot!, targetsInRange)
            ?? escalatingTarget(gameState, bot!, targetsInRange)
            ?? (hasSword(bot!) ? randomOtherLivingPlayer(gameState, bot!, targetsInRange) : undefined);
        if (!target) {
            return { kind: 'endTurn', event: { playerId: bot!.user.id, actionType: PlayerActionType.playerEndTurn } };
        }
        return {
            kind: 'attack',
            event: {
                playerId: bot!.user.id,
                actionType: PlayerActionType.playerAttack,
                targets: hasMachineGun(bot!) ? targetsInRange.map(candidate => candidate.user) : [target.user],
                damageRoll: usesSingleDieAttack(bot!) ? [4] : [6, 1],
                modifiers: attackModifierFor(bot!)
            }
        };
    }
    return undefined;
}

/** Resolves host-delivered card prompts without opening a UI for a bot. */
export function chooseBotChoice(gameState: GameState, playerChoice: PlayerChoice): string | undefined {
    const bot = playerFor(gameState, playerChoice.choice.type === ChoiceType.weirdWoods
        ? playerChoice.playerId
        : playerChoice.choice.target);
    if (!isBot(bot)) return undefined;
    switch (playerChoice.choice.type) {
        case ChoiceType.equipment: {
            const source = gameState.lobby.playerList.find(player => player.user.id !== bot!.user.id && player.piece.items.length > 0);
            const item = source?.piece.items[0];
            return source && item ? `${source.user.id},${item.name}` : 'skip';
        }
        case ChoiceType.hermitGreed: {
            const item = bot!.piece.items[0];
            return item ? `${bot!.user.id},${item.name}` : 'damage';
        }
        case ChoiceType.move:
            return JSON.stringify(rollDice([6, 4]).reduce((dice, value, index, all) =>
                index === 1 && all[0] + value === 7 ? [6, 4] : [...dice, value], [] as number[]));
        case ChoiceType.rerollMovement:
            return JSON.stringify(rollDice([6, 4]));
        case ChoiceType.teleport:
            return 'normal';
        case ChoiceType.area:
            return gameState.lobby.decks.areas.cards[0]?.name;
        case ChoiceType.reveal:
            return 'yes';
        case ChoiceType.draw:
            return lowestDamageAlly(gameState, bot!) || bot!.piece.damage > 0 ? 'green' : 'black';
        case ChoiceType.target: {
            const wantsHealing = /Aid|Huddle|Nurturance/i.test(playerChoice.choice.card.name);
            const hostile = knownHostileTarget(gameState, bot!);
            if (isOffensiveTargetCard(playerChoice.choice.card)) {
                return (hostile ?? randomOtherLivingPlayer(gameState, bot!))?.user.id ?? 'skip';
            }
            if (/^Hermit's /i.test(playerChoice.choice.card.name)) {
                const unconfirmedBot = gameState.lobby.playerList.find(candidate => candidate.user.isBot
                    && candidate.user.id !== bot!.user.id
                    && !candidate.piece.dead
                    && gameState.botFactionKnowledge?.[bot!.user.id]?.[candidate.user.id] === undefined);
                return unconfirmedBot?.user.id ?? 'skip';
            }
            return (wantsHealing ? lowestDamageAlly(gameState, bot!) : hostile)?.user.id ?? 'skip';
        }
        case ChoiceType.weirdWoods: {
            const target = playerFor(gameState, playerChoice.choice.target);
            return target && isAlly(bot!, target) && target.piece.damage > 0 ? 'heal' : 'damage';
        }
        case ChoiceType.showCard:
            return bot!.user.id;
        default:
            return undefined;
    }
}
