import * as React from 'react';
import { useAppDispatch, useAppSelector } from '../store/hooks';
import { useNavigate } from 'react-router';
import { PeerState } from '../store/peer/peerTypes';
import LinearProgress from '@mui/material/LinearProgress';
import { attack, choice, connectPeer, endGameAfterDisconnect, endHostedGame, endTurn, move, removeEvent, replaceDisconnectedPlayer, updateGameState, useAbility } from '../store/connection/connectionActions';
import { ChoiceType, Decks, Player, PlayerChoice, rollDice, UserDetails, ConnectionState, ModalState, PlayerActionType } from '../helpers/common';
import { PeerConnection } from '../helpers/peer';
import { isTestMode } from '../store';
import PlayerList from './PlayerList';
import { attackModifierFor, attackRangeFor, CustomItemFunction, getCompass, hasMachineGun, hasSword, usesSingleDieAttack } from '../helpers/cardAction';
import LogList from './LogList';
import ChoiceDialog from './ChoiceDialog';
import EventDialog from './EventDialog';
import PlayerGui from './PlayerGui';
import DevMenu from './DevMenu';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import Slider from '@mui/material/Slider';
import useMediaQuery from '@mui/material/useMediaQuery';
import { chooseBotAction, chooseBotChoice, DEFAULT_BOT_THINK_TIME_MS } from '../store/connection/botController';
import DisconnectDialog from './DisconnectDialog';
import { initialState } from '../store/connection/connectionReducer';
import { startPeer, stopPeerSession } from '../store/peer/peerActions';
import HostQuitDialog from './HostQuitDialog';
import { eventDialogText } from '../helpers/dialogText';
import MobileGameOverview from './MobileGameOverview';

const GameRender = React.lazy(() => import('./GameRender'));

function GameBoard() {
  const navigate = useNavigate();
  const peer = useAppSelector((state) => state.peer) as PeerState;
  const connection = useAppSelector((state) => state.connection) as ConnectionState;
  const isMobile = useMediaQuery('(max-width:1000px)');
  const dispatch = useAppDispatch();
  const [choiceModalState, setChoiceModal] = React.useState<ModalState>({ openModal: false, modalMessage: '' });
  const [choiceEventState, setEventModal] = React.useState<ModalState>({ openModal: false, modalMessage: '' });
  const [choiceQueue, setChoiceQueue] = React.useState<PlayerChoice[]>([]);
  const [activeChoice, setActiveChoice] = React.useState<PlayerChoice>();
  const [revealedCharacterChoice, setRevealedCharacterChoice] = React.useState<PlayerChoice>();
  const [hostQuitDialogOpen, setHostQuitDialogOpen] = React.useState(false);
  const [turnNoticeOpen, setTurnNoticeOpen] = React.useState(false);
  const [canvasScale, setCanvasScale] = React.useState(1);
  const botChoicePending = React.useRef(false);
  const counterattackChoiceKey = React.useRef<string | undefined>(undefined);
  const reconnectInFlight = React.useRef(false);
  const lastLocalTurnNotice = React.useRef<string | undefined>(undefined);
  const counterattack = connection.gameState.pendingCounterattack;

  React.useEffect(() => {
    if (!connection.gameState.started || !peer.id || PeerConnection.getPeer()) return;
    void dispatch(startPeer(peer.id));
  }, [connection.gameState.started, dispatch, peer.id]);

  React.useEffect(() => {
    const disconnected = connection.gameState.disconnectedPlayer;
    const hostId = connection.gameState.hostId;
    if (!disconnected?.isHost || peer.id === hostId || !peer.id || !hostId || !peer.userData?.userName || !peer.userData.color) return;
    let active = true;
    const reconnect = () => {
      if (!active || reconnectInFlight.current || !PeerConnection.getPeer()) return;
      reconnectInFlight.current = true;
      Promise.resolve(dispatch(connectPeer(hostId, {
        id: peer.id!,
        userName: peer.userData!.userName!,
        color: peer.userData!.color!
      }))).finally(() => {
        reconnectInFlight.current = false;
      });
    };
    reconnect();
    const timer = window.setInterval(reconnect, 3_000);
    return () => {
      active = false;
      window.clearInterval(timer);
    };
  }, [connection.gameState.disconnectedPlayer, connection.gameState.hostId, dispatch, peer.id, peer.userData?.color, peer.userData?.userName]);

  React.useEffect(() => {
    const currentPlayer = connection.gameState.lobby.playerList.find(player => player.user.id === connection.gameState.currentPlayer);
    const isLocalTurn = connection.gameState.started
      && !connection.gameState.gameEnded
      && !connection.gameState.disconnectedPlayer
      && connection.gameState.currentPlayer === peer.id
      && !currentPlayer?.piece.dead;
    if (!isLocalTurn) {
      lastLocalTurnNotice.current = undefined;
      setTurnNoticeOpen(false);
      return;
    }
    if (lastLocalTurnNotice.current === connection.gameState.currentPlayer || connection.playerEvents.length > 0) return;
    lastLocalTurnNotice.current = connection.gameState.currentPlayer;
    setTurnNoticeOpen(true);
  }, [connection.gameState.currentPlayer, connection.gameState.disconnectedPlayer, connection.gameState.gameEnded, connection.gameState.lobby.playerList, connection.gameState.started, connection.playerEvents.length, peer.id]);

  React.useEffect(() => {
    if (!isTestMode && ((!connection.id && (connection.gameState.hostId !== peer.id))
      || !connection.gameState.started)) {
      navigate('/');
    }

    PeerConnection.setCallback(handleChoice);
  });

  React.useEffect(() => {
    if (connection.gameState.hostId !== connection.peerId) return;
    if (connection.gameState.disconnectedPlayer || botChoicePending.current || connection.playerEvents.length > 0 || activeChoice || choiceQueue.length > 0 || choiceModalState.openModal) return;
    const botAction = chooseBotAction(connection.gameState);
    if (!botAction) return;
    const timer = window.setTimeout(() => {
      if (botAction.kind === 'move') dispatch(move(botAction.event));
      else if (botAction.kind === 'attack') dispatch(attack(botAction.event));
      else if (botAction.kind === 'endTurn') dispatch(endTurn(botAction.event));
      else dispatch(useAbility(botAction.event));
    }, connection.gameState.botThinkTimeMs ?? DEFAULT_BOT_THINK_TIME_MS);
    return () => window.clearTimeout(timer);
  }, [connection.gameState, connection.playerEvents.length, dispatch, peer.id, activeChoice, choiceQueue.length, choiceModalState.openModal]);

  const handleChoiceModalClose = () => {
    setChoiceModal({ openModal: false, modalMessage: '' });
  };

  const handleEventModalClose = React.useCallback(() => {
    setEventModal({ openModal: false, modalMessage: '' });
    dispatch(removeEvent());
  }, [dispatch]);

  const handleRevealedCharacterClose = () => {
    if (!revealedCharacterChoice) return;
    const dismissedChoice = { ...revealedCharacterChoice, result: 'dismissed' };
    setRevealedCharacterChoice(undefined);
    dispatch(choice(dismissedChoice));
  };

  const choiceText = (playerChoice: PlayerChoice) => {
    switch (playerChoice.choice.type) {
      case ChoiceType.equipment:
        return playerChoice.playerId === playerChoice.choice.target ? 'Choose Equipment to Give.' : 'Choose Equipment to Steal.';
      case ChoiceType.hermitGreed:
        return 'Give an item or take damage.';
      case ChoiceType.hermitFaction:
        return 'Choose its result.';
      case ChoiceType.move:
        return 'Choose Your Movement Roll.';
      case ChoiceType.rerollMovement:
        return 'Reroll movement.';
      case ChoiceType.teleport:
        return 'Move normally or teleport to an adjacent area.';
      case ChoiceType.area:
        return 'Choose Your Destination.';
      case ChoiceType.reveal:
        return 'Reveal Your Character?';
      case ChoiceType.showCard:
        return 'Show Your Character Card.';
      case ChoiceType.target:
        return 'Choose Your Target.';
      case ChoiceType.draw:
        return 'Choose Deck to Draw From.';
      case ChoiceType.weirdWoods:
        return 'Choose an effect for the targeted player.';
      case ChoiceType.counterattack:
        return 'You were attacked.';
      default:
        return 'default choice text';
    }
  }

  const attackTargetsFor = (currentPlayer: Player): UserDetails[] => {
    return attackRangeFor(connection.gameState, currentPlayer).map(player => player.user);
  };

  const handleAttack = (targets?: UserDetails[] | undefined) => {
    const currentPlayer = connection.gameState.lobby.playerList.filter(x => x.user.id === connection.gameState.currentPlayer)[0];

    if (!targets) {
      if (currentPlayer.piece.items.length > 0) {
        //Modified by Items Attack
        const results = currentPlayer.piece.items.map(x => CustomItemFunction(connection.gameState, x));
        if (results.filter(x => x.choice).length > 0) {
          //Player has choices to make
          const result = results.filter(x => x.choice)[0]!;
          handleChoice({ choice: result.choice!, playerId: currentPlayer.user.id, actionType: PlayerActionType.playerChoice })
          return;
        }
      }
      const availableTargets = attackTargetsFor(currentPlayer);

      if (hasMachineGun(currentPlayer)) {
        if (availableTargets.length > 0) handleAttack(availableTargets);
        return;
      }

      if (availableTargets.length === 0) return;
      setChoiceModal({
        modalMessage: 'Choose Your Target.',
        targets: availableTargets,
        hasSword: hasSword(currentPlayer), openModal: true
      });
    }
    else {
      setChoiceModal({ openModal: false, modalMessage: '' });
      if (connection.gameState.pendingCounterattack?.responderId === currentPlayer.user.id) {
        setActiveChoice(undefined);
      }
      dispatch(attack({
        targets,
        damageRoll: usesSingleDieAttack(currentPlayer) ? rollDice([4]) : rollDice([6, 4]),
        modifiers: attackModifierFor(currentPlayer),
        playerId: currentPlayer.user.id,
        actionType: PlayerActionType.playerAttack
      }));
    }
  }

  const handleChoice = (playerChoice: PlayerChoice) => {
    if (connection.gameState.disconnectedPlayer) return;
    if (playerChoice.choice.type === ChoiceType.showCard && playerChoice.choice.target !== peer.id) return;
    if (playerChoice.choice.type === ChoiceType.showCard && !playerChoice.result) {
      setRevealedCharacterChoice(playerChoice);
      return;
    }
    if (playerChoice.choice.type === ChoiceType.counterattack && playerChoice.result === 'skip') {
      setActiveChoice(undefined);
      setChoiceModal({ openModal: false, modalMessage: '' });
      dispatch(useAbility({ playerId: playerChoice.playerId, actionType: PlayerActionType.playerAbility, skipCounterattack: true }));
      return;
    }
    if (playerChoice.result) {
      setActiveChoice(undefined);
      setChoiceModal({ openModal: false, modalMessage: '' });
      dispatch(choice(playerChoice));
    }
    else {
      setChoiceQueue(queue => [...queue, playerChoice]);
    }
  }

  React.useEffect(() => {
    if (!counterattack || counterattack.responderId !== peer.id) {
      counterattackChoiceKey.current = undefined;
      return;
    }
    const key = `${counterattack.responderId}:${counterattack.attackerId}`;
    if (counterattackChoiceKey.current === key) return;
    counterattackChoiceKey.current = key;
    setChoiceQueue(queue => [...queue, {
      playerId: counterattack.responderId,
      actionType: PlayerActionType.playerChoice,
      choice: {
        card: { name: 'Counterattack', drawDeck: Decks.characters },
        type: ChoiceType.counterattack,
        target: counterattack.attackerId
      }
    }]);
  }, [counterattack, peer.id]);

  React.useEffect(() => {
    if (connection.gameState.disconnectedPlayer || connection.playerEvents.length > 0 || choiceModalState.openModal || activeChoice || choiceQueue.length === 0 || botChoicePending.current) return;
    const [nextChoice, ...remainingChoices] = choiceQueue;
    setChoiceQueue(remainingChoices);
    const botResult = chooseBotChoice(connection.gameState, nextChoice);
    if (botResult !== undefined) {
      botChoicePending.current = true;
      window.setTimeout(() => {
        botChoicePending.current = false;
        dispatch(choice({ ...nextChoice, result: botResult }));
      }, connection.gameState.botThinkTimeMs ?? DEFAULT_BOT_THINK_TIME_MS);
      return;
    }
    setActiveChoice(nextChoice);
  }, [activeChoice, choiceModalState.openModal, choiceQueue, connection.gameState, connection.playerEvents.length, dispatch]);

  const handleMove = () => {
    const currentPlayer = connection.gameState.lobby.playerList.filter(x => x.user.id === connection.gameState.currentPlayer)[0];
    const moveRoll = rollDice([6, 4]);
    const compass = getCompass(currentPlayer);

    if (compass) {
      handleChoice({
        playerId: connection.gameState.currentPlayer,
        choice: { card: compass, type: ChoiceType.move, value: (moveRoll[0] + moveRoll[1]).toString(), target: connection.gameState.currentPlayer },
        actionType: PlayerActionType.playerAttack
      });
      return;
    }

    dispatch(move({ playerId: connection.gameState.currentPlayer, moveRoll, actionType: PlayerActionType.playerMove }))
  }

  const handleEndTurn = () => {
    dispatch(endTurn({ playerId: connection.gameState.currentPlayer, actionType: PlayerActionType.playerEndTurn }));
  };

  const handleQuit = () => {
    if (connection.peerId === connection.gameState.hostId) {
      setHostQuitDialogOpen(true);
      return;
    }
    void PeerConnection.closePeerSession().finally(() => dispatch(stopPeerSession()));
    dispatch(updateGameState(initialState.gameState));
    navigate('/');
  };

  const activePlayer = connection.gameState.lobby.playerList.find(player => player.user.id === connection.gameState.currentPlayer);
  const canAttack = Boolean(activePlayer && activePlayer.user.id === peer.id && activePlayer.piece.moved
    && !activePlayer.piece.attacked && !activePlayer.piece.dead && attackTargetsFor(activePlayer).length > 0);
  const activeChoiceModal = activeChoice
    ? { openModal: true, modalMessage: choiceText(activeChoice), playerChoice: activeChoice }
    : choiceModalState;

  const winnerNames = connection.gameState.lobby.playerList
    .filter(player => connection.gameState.victors?.includes(player.user.id))
    .map(player => player.user.userName);

  return (
    <React.Fragment>
      {isTestMode ? <DevMenu handleAttack={handleAttack} handleChoice={handleChoice} handleMove={handleMove} /> : undefined}
      {isMobile ? <MobileGameOverview userId={peer.id!} /> : !peer.loading && !connection.loading && connection.gameState.lobby.decks[Decks.areas].cards.length > 1 ?
        <React.Suspense fallback={<LinearProgress />}><GameRender scale={canvasScale} /></React.Suspense> : <LinearProgress />
      }
      {isMobile ? <Box aria-hidden sx={{
        position: 'fixed', top: 0, right: 0, bottom: 0, width: 80, zIndex: 1100, pointerEvents: 'none',
        background: 'linear-gradient(270deg, rgba(25, 34, 49, 0.98), rgba(36, 52, 77, 0.9))',
        borderLeft: '2px solid rgba(255, 255, 255, 0.3)', boxShadow: '-3px 0 12px rgba(0, 0, 0, 0.4)'
      }} /> : undefined}
      {isMobile ? undefined : <Box aria-hidden sx={{
        position: 'fixed', top: 0, left: 0, right: 0, height: '82px', zIndex: 1100, pointerEvents: 'none',
        background: 'linear-gradient(180deg, rgba(25, 34, 49, 0.98), rgba(36, 52, 77, 0.92))',
        borderBottom: '2px solid rgba(255, 255, 255, 0.3)', boxShadow: '0 3px 12px rgba(0, 0, 0, 0.45)',
        '&::after': { content: '""', position: 'absolute', inset: '6px 8px', borderBottom: '1px solid rgba(255, 255, 255, 0.15)' }
      }} />}
      {isMobile ? undefined : <Box aria-hidden sx={{
        position: 'fixed', bottom: 0, left: 0, right: 0, height: '82px', zIndex: 1100, pointerEvents: 'none',
        background: 'linear-gradient(0deg, rgba(25, 34, 49, 0.98), rgba(36, 52, 77, 0.92))',
        borderTop: '2px solid rgba(255, 255, 255, 0.3)', boxShadow: '0 -3px 12px rgba(0, 0, 0, 0.45)',
        '&::after': { content: '""', position: 'absolute', inset: '6px 8px', borderTop: '1px solid rgba(255, 255, 255, 0.15)' }
      }} />}
      {isMobile ? undefined : <Box sx={{ position: 'fixed', left: 24, bottom: 90, zIndex: 1201, width: 220, paddingX: 1.5, paddingTop: 0.5, borderRadius: 1, backgroundColor: 'rgba(25, 34, 49, 0.92)' }}>
        <Slider
          id='board-zoom-slider'
          aria-label='Board zoom'
          min={0.5}
          max={1.5}
          step={0.25}
          marks
          value={canvasScale}
          valueLabelDisplay='auto'
          getAriaValueText={value => `${value.toFixed(2)} times zoom`}
          onChange={(_event, value) => setCanvasScale(value as number)}
        />
      </Box>}
      {isMobile ? undefined : <PlayerList userId={peer.id!} />}
      <LogList noText={isMobile} />
      <PlayerGui compact={isMobile} handleMove={handleMove} handleEndTurn={handleEndTurn} handleAttack={handleAttack} handleChoice={handleChoice} canAttack={canAttack} onQuit={handleQuit} />
      <Dialog open={connection.gameState.gameEnded === true && connection.playerEvents.length === 0}>
        <DialogTitle>Game Over</DialogTitle>
        <DialogContent>
          <Typography>{connection.gameState.endedByHost ? 'The host ended the game.' : connection.gameState.endedByDisconnect ? 'The host ended the game after a player disconnected.' : winnerNames.length === 1 ? `${winnerNames[0]} wins!` : `${winnerNames.join(', ')} win!`}</Typography>
        </DialogContent>
      </Dialog>
      <ChoiceDialog handleModalClose={handleChoiceModalClose} modalState={activeChoiceModal} handleAttack={handleAttack} handleChoice={handleChoice} />
      {turnNoticeOpen ?
        <EventDialog
          playerEvent={{ playerId: peer.id!, actionType: PlayerActionType.playerEndTurn, animateDice: false }}
          handleModalClose={() => setTurnNoticeOpen(false)}
          modalState={{ openModal: true, modalMessage: "It's your turn." }} />
        : revealedCharacterChoice ?
          <EventDialog
            playerEvent={{ playerId: revealedCharacterChoice.playerId, actionType: PlayerActionType.playerChoice }}
            handleModalClose={handleRevealedCharacterClose}
            revealedCard={revealedCharacterChoice.choice.card}
            modalState={{
              openModal: true,
              modalMessage: `${connection.gameState.lobby.playerList.find(player => player.user.id === revealedCharacterChoice.choice.value)?.user.userName ?? 'A player'}'s character.`
            }} />
          : connection.playerEvents.length > 0 ?
            <EventDialog playerEvent={connection.playerEvents[0]} handleModalClose={handleEventModalClose}
              revealedCard={connection.playerEvents[0].revealedCard} card={connection.playerEvents[0].card}
              modalState={{ ...choiceEventState, openModal: true, modalMessage: eventDialogText(connection.gameState.lobby.playerList, connection.playerEvents[0]) ?? '' }} />
            : undefined}
      <DisconnectDialog
        disconnectedPlayer={connection.gameState.disconnectedPlayer}
        isHost={connection.peerId === connection.gameState.hostId}
        onQuit={handleQuit}
        onReplaceWithBot={() => {
          const playerId = connection.gameState.disconnectedPlayer?.playerId;
          if (playerId) dispatch(replaceDisconnectedPlayer(playerId));
        }}
        onEndGame={() => {
          const playerId = connection.gameState.disconnectedPlayer?.playerId;
          if (playerId) dispatch(endGameAfterDisconnect(playerId));
        }} />
      <HostQuitDialog open={hostQuitDialogOpen} onCancel={() => setHostQuitDialogOpen(false)} onConfirm={() => {
        setHostQuitDialogOpen(false);
        dispatch(endHostedGame());
        navigate('/');
      }} />
    </React.Fragment>
  );
}

export default GameBoard;
