import * as React from 'react';
import Avatar from '@mui/material/Avatar';
import Box from '@mui/material/Box';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import Grid from '@mui/material/Grid';
import Paper from '@mui/material/Paper';
import Stack from '@mui/material/Stack';
import Tab from '@mui/material/Tab';
import Tabs from '@mui/material/Tabs';
import Typography from '@mui/material/Typography';
import { CardModalState, ConnectionState, Decks, Player } from '../helpers/common';
import { useAppSelector } from '../store/hooks';
import Dialog from '@mui/material/Dialog';

type MobileBoardView = 'locations' | 'players';

const fullWidthContentSx = {
    width: '100%',
    minWidth: 0,
    maxWidth: '100%',
    boxSizing: 'border-box',
    overflowX: 'hidden',
    contain: 'inline-size'
} as const;

function PlayerChip({ player }: { player: Player }) {
    return <Avatar sx={{ backgroundColor: player.user.color }}>{' '}</Avatar>;
}

function MobileGameOverview({ userId }: { userId: string }) {
    const connection = useAppSelector((state) => state.connection) as ConnectionState;
    const [view, setView] = React.useState<MobileBoardView>('locations');
    const { lobby } = connection.gameState;
    const areaCards = lobby.decks[Decks.areas]?.cards ?? [];
    const [modalState, setModal] = React.useState<CardModalState>({ openModal: false, src: '', alt: '' });

    // Locations normally scroll while the shorter Players view does not. Reserve
    // the scrollbar space so changing views cannot change the content width.
    return <Box component='main' aria-label='Mobile game board' sx={{ position: 'fixed', top: 0, right: 80, bottom: 0, left: 0, width: 'auto', boxSizing: 'border-box', overflowX: 'hidden', overflowY: 'auto', scrollbarGutter: 'stable', contain: 'inline-size', padding: 1.5, paddingRight: 0, paddingBottom: 3, backgroundColor: 'background.default' }}>
        <Paper elevation={4} sx={{ position: 'sticky', top: 4, zIndex: 1, ...fullWidthContentSx, marginBottom: 1.5, borderRadius: 3, overflow: 'hidden' }}>
            <Tabs aria-label='Mobile board view' value={view} onChange={(_event, nextView: MobileBoardView) => setView(nextView)} variant='fullWidth' sx={{
                width: '100%', minWidth: 0, overflow: 'hidden',
                '& .MuiTabs-list, & .MuiTabs-flexContainer': { display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', width: '100%', minWidth: 0 },
                '& .MuiTab-root': { width: '100%', minWidth: 0, maxWidth: '100%', boxSizing: 'border-box', color: 'text.secondary' },
                '& .MuiTab-root.Mui-selected': { color: '#9ed0ff', backgroundColor: 'rgba(62, 96, 145, 0.7)', fontWeight: 700 },
                '& .MuiTabs-indicator': { height: 4, backgroundColor: '#9ed0ff' }
            }}>
                <Tab value='locations' label='Locations' />
                <Tab value='players' label='Players' />
            </Tabs>
        </Paper>

        <Box sx={fullWidthContentSx}>
            {view === 'locations' ?
                <Grid container spacing={1.5} sx={fullWidthContentSx}>
                {areaCards.map((area, position) => {
                    const occupants = lobby.playerList.filter(player => !player.piece.dead && player.piece.position === position);
                    return <Grid key={`${area.name}-${position}`} size={12}>
                        <Card variant='outlined'>
                            <CardContent sx={{ paddingTop: 2, '&:last-child': { paddingBottom: 2 }, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                {
                                    occupants.length > 0 ?
                                        <Stack direction='row' flexWrap='wrap' gap={0.75}>
                                            {occupants.map(player => <PlayerChip key={player.user.id} player={player} />)}
                                        </Stack> :
                                        <Box />
                                }

                                <Box sx={{ cursor: 'zoom-in' }} onClick={(e) => {
                                    e.stopPropagation();
                                    setModal({
                                        src: `${import.meta.env.BASE_URL}assets/game/areas/${area.name}.jpg`, alt: area.name, openModal: true
                                    });
                                }} component='img' width={35 * 1.5} height={50 * 1.5}
                                    alt='Character Card' src={`${import.meta.env.BASE_URL}assets/game/areas/${area.name}.jpg`} />
                            </CardContent>
                        </Card>
                    </Grid>;
                })}
                </Grid> :
                <Grid container spacing={1.5} sx={fullWidthContentSx}>
                {lobby.playerList.map(player => {
                    return <Grid key={player.user.id} size={12} sx={{ minWidth: 0, maxWidth: '100%' }}>
                        <Card variant='outlined' sx={{ width: '100%', minWidth: 0, maxWidth: '100%', boxSizing: 'border-box', opacity: player.piece.dead ? 0.55 : 1, overflow: 'hidden' }}>
                            <CardContent sx={{ position: 'relative', minWidth: 0, overflow: 'hidden', paddingTop: 0, '&:last-child': { minHeight: 96, paddingY: 2, paddingRight: 13 } }}>
                                <Box sx={{ display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 1, minWidth: 0 }}>
                                    <Grid sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 0 }}>
                                        <Avatar sx={{ backgroundColor: player.user.color }}>{' '}</Avatar>
                                        <Typography variant='h5' noWrap sx={{ minWidth: 0, marginTop: '4px' }}>{player.user.userName}</Typography>
                                    </Grid>
                                    <Typography variant='h5' noWrap sx={{ marginTop: '8px' }}>{player.piece.dead ? 'Dead' : `Damage: ${player.piece.damage}`}</Typography>
                                </Box>
                                <Box sx={{ position: 'absolute', top: '50%', right: '12px', transform: 'translateY(-50%)', cursor: 'zoom-in', backgroundColor: player.user.color, minWidth: 'unset', padding: '10px' }}>
                                    <Box sx={{ filter: player.piece.dead ? 'grayscale(100%)' : 'none' }} onClick={(e) => {
                                        e.stopPropagation();
                                        setModal({
                                            src: player.user.id === userId || player.piece.revealed ?
                                                `${import.meta.env.BASE_URL}assets/game/characters/${player.piece.character.name}.jpg` : `${import.meta.env.BASE_URL}assets/game/card_backs/characters.jpg`, alt: 'Character Card', openModal: true
                                        });
                                    }} component='img' width={35 * 1.5} height={50 * 1.5}
                                        alt='Character Card' src={player.user.id === userId || player.piece.revealed ?
                                            `${import.meta.env.BASE_URL}assets/game/characters/${player.piece.character.name}.jpg` : `${import.meta.env.BASE_URL}assets/game/card_backs/characters.jpg`} />
                                </Box>
                            </CardContent>
                        </Card>
                    </Grid>;
                })}
                </Grid>}
        </Box>
        <Dialog
            open={modalState.openModal}
            onClose={() => setModal({ openModal: false, alt: '', src: '' })}
        >
            {modalState.src && (<Box component='img' height={600} src={modalState.src} alt={modalState.alt} />)}
        </Dialog>
    </Box>;
}

export default MobileGameOverview;
