import * as React from 'react';
import { useAppSelector } from '../store/hooks';
import Box from '@mui/material/Box';
import Divider from '@mui/material/Divider';
import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemText from '@mui/material/ListItemText';
import ListItemAvatar from '@mui/material/ListItemAvatar';
import { Card, Player, ConnectionState, CardModalState } from '../helpers/common';
import Grid from '@mui/material/Grid';
import Typography from '@mui/material/Typography';
import { themeOptions } from '../helpers/theme';
import { SimplePaletteColorOptions } from '@mui/material/styles';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import ListItemIcon from '@mui/material/ListItemIcon';
import { GiDeathSkull, GiBackup } from 'react-icons/gi';

interface ItemList {
    items: Card[],
    anchor?: HTMLElement,
    player?: string
}

function PlayerList({ userId }: { userId: string }) {
    const connection = useAppSelector((state) => state.connection) as ConnectionState;
    const [itemList, setItemList] = React.useState<ItemList>({ items: [] });
    const [showList, setShowList] = React.useState<boolean>(false);
    const [modalState, setModal] = React.useState<CardModalState>({ openModal: false, src: '', alt: '' });

    return <React.Fragment>
        <Grid sx={{ bottom: 88, right: 16, position: 'absolute', zIndex: 1200 }}
            display='flex' justifyContent='center' alignItems='top'>
            {
                itemList.anchor && showList ?
                    <Box sx={{ marginRight: 2, backgroundColor: themeOptions.palette!.background!.default!, paddingTop: 2, minWidth: '300px' }}>
                        <Typography sx={{ marginLeft: 1 }} variant='h5'>Equipment</Typography>
                        <Divider variant='fullWidth' sx={{ marginBottom: 1 }} />
                        <List disablePadding sx={{ overflowY: 'auto', overflowX: 'hidden', maxHeight: '250px', backgroundColor: themeOptions.palette!.background!.paper! }}>
                            {
                                itemList.items.length == 0 ?
                                    <ListItem sx={{ height: '66px', width:'220px', paddingTop: '16px', verticalAlign: 'top', display: 'inline-block' }}><ListItemText>None</ListItemText></ListItem> :
                                    itemList.items.map((x: Card, i: number) =>
                                        <React.Fragment key={`item_list_item_${i}`}>
                                            {i === 0 ? undefined : <Divider variant='fullWidth' component='li' />}
                                            <ListItem sx={{ cursor: 'zoom-in' }} onClick={() => setModal({ src: `${import.meta.env.BASE_URL}assets/game/${x.drawDeck}/${x.name}.jpg`, alt: x.name, openModal: true })}>
                                                <ListItemText primary={x.name} />
                                                <ListItemAvatar>
                                                    <Box sx={{ float: 'right' }} component='img' width={35} height={50} alt={x.name} src={`${import.meta.env.BASE_URL}assets/game/${x.drawDeck}/${x.name}.jpg`} />
                                                </ListItemAvatar>
                                            </ListItem>
                                        </React.Fragment>
                                    )
                            }
                        </List>
                    </Box> : undefined
            }
            {
                showList ?
                    <Box sx={{ backgroundColor: themeOptions.palette!.background!.default!, paddingTop: 2, minWidth: '300px', maxHeight: '350px' }}>
                        <Typography sx={{ marginLeft: 1 }} variant='h5'>Players</Typography>
                        <Divider variant='fullWidth' sx={{ marginBottom: 1 }} />
                        <List disablePadding sx={{ overflowY: 'auto', overflowX: 'hidden', maxHeight: '250px', backgroundColor: themeOptions.palette!.background!.paper! }}>
                            {
                                connection.gameState.lobby.playerList.map((x: Player, i: number) =>
                                    <React.Fragment key={`list_item_${i}`}>
                                        {i === 0 ? undefined : <Divider variant='fullWidth' component='li' />}
                                        <ListItem id={`list_item_${i}`} onClick={(e) => x.piece.dead ? undefined : setItemList({ items: x.piece.items, anchor: e.currentTarget, player: x.user.userName })}
                                            sx={{
                                                cursor: x.piece.dead ? 'default' : 'pointer', backgroundColor: itemList.anchor?.id === `list_item_${i}` ?
                                                    (themeOptions.palette?.info as SimplePaletteColorOptions).main : undefined
                                            }}>
                                            {x.piece.dead ? <ListItemIcon sx={{ minWidth: '30px' }}><GiDeathSkull color="#f44336" /></ListItemIcon> : undefined}
                                            <ListItemText primary={x.user.userName} />
                                            <ListItemAvatar sx={{ cursor: 'zoom-in', backgroundColor: x.user.color, minWidth: 'unset', padding: '10px' }}>
                                                <Box sx={{ float: 'right', filter: x.piece.dead ? 'grayscale(100%)' : 'none' }} onClick={(e) => {
                                                    e.stopPropagation();
                                                    setModal({
                                                        src: x.user.id === userId || x.piece.revealed ?
                                                            `${import.meta.env.BASE_URL}assets/game/characters/${x.piece.character.name}.jpg` : `${import.meta.env.BASE_URL}assets/game/card_backs/characters.jpg`, alt: 'Character Card', openModal: true
                                                    });
                                                }} component='img' width={35} height={50}
                                                    alt='Character Card' src={x.user.id === userId || x.piece.revealed ?
                                                        `${import.meta.env.BASE_URL}assets/game/characters/${x.piece.character.name}.jpg` : `${import.meta.env.BASE_URL}assets/game/card_backs/characters.jpg`} />
                                            </ListItemAvatar>
                                        </ListItem>
                                    </React.Fragment>
                                )
                            }
                        </List>
                    </Box> : undefined
            }
        </Grid>
        <Button sx={{ height: '54.75px', paddingX: 3, fontSize: '1.3125rem', marginLeft: 2, bottom: 16, right: 16, position: 'absolute', zIndex: 1200, }} variant='contained' onClick={() => setShowList(!showList)}>
            <GiBackup style={{ marginRight: 16, marginTop: '-4px' }} />Players
        </Button>

        <Dialog
            open={modalState.openModal}
            onClose={() => setModal({ openModal: false, alt: '', src: '' })}
        >
            {modalState.src && (<Box component='img' height={600} src={modalState.src} alt={modalState.alt} />)}
        </Dialog>
    </React.Fragment>;
}

export default PlayerList;
