import Box from '@mui/material/Box';
import Dialog from '@mui/material/Dialog';
import { ChoiceType, ConnectionState, ModalState, PlayerChoice, rollDice, UserDetails } from '../helpers/common';
import Typography from '@mui/material/Typography';
import React from 'react';
import List from '@mui/material/List';
import Button from '@mui/material/Button';
import Divider from '@mui/material/Divider';
import ListItem from '@mui/material/ListItem';
import { useAppSelector } from '../store/hooks';
import { themeOptions } from '../helpers/theme';
import { SimplePaletteColorOptions } from '@mui/material/styles';

interface AttackTarget {
    hoverTarget?: UserDetails | undefined,
    clickTarget?: UserDetails | undefined
}

interface ChoiceTarget {
    hoverTarget?: string | undefined,
    clickTarget?: string | undefined,
    hoverTarget2?: string | undefined,
    clickTarget2?: string | undefined,
}

export default function ChoiceDialog({ handleModalClose = () => { }, modalState, handleAttack = (targets) => targets, handleChoice = (playerChoice) => playerChoice }:
    {
        handleModalClose: () => void,
        modalState: ModalState,
        handleAttack: (targets?: UserDetails[] | undefined) => void,
        handleChoice: (playerChoice: PlayerChoice) => void
    }) {

    const hoverColor = (themeOptions.palette?.secondary as SimplePaletteColorOptions).main;
    const clickColor = (themeOptions.palette?.secondary as SimplePaletteColorOptions).main;
    const connection = useAppSelector((state) => state.connection) as ConnectionState;
    const [attackTarget, setAttackTarget] = React.useState<AttackTarget>({});
    const [choiceTarget, setChoiceTarget] = React.useState<ChoiceTarget>({});

    const attackElement = (targets: UserDetails[], hasSword: boolean) => {
        return targets.length === 0 ?
            <Box sx={{ width: '100%' }}>
                <Button sx={{ marginTop: 2, float: 'right' }} variant='contained' onClick={() => { setAttackTarget({ clickTarget: undefined, hoverTarget: undefined }); handleModalClose(); }}>Ok</Button>
            </Box> :
            <Box sx={{ width: '100%' }}>
                <List disablePadding sx={{ backgroundColor: themeOptions.palette!.background!.paper!, width: '100%', overflowY: 'auto', overflowX: 'hidden', maxHeight: '200px', marginBottom: 2, marginTop: 2 }}>
                    {
                        targets.map((x, i) => <React.Fragment key={`attack_target_${i}`}>
                            {i === 0 ? undefined : <Divider variant='fullWidth' component='li' />}
                            <ListItem sx={{
                                cursor: 'pointer', color: x === attackTarget.clickTarget ? 'white' : undefined, backgroundColor: x === attackTarget.clickTarget ? clickColor
                                    : x === attackTarget.hoverTarget ? hoverColor : undefined
                            }}
                                onMouseEnter={() => setAttackTarget({ ...attackTarget, hoverTarget: x })}
                                onMouseLeave={() => setAttackTarget({ ...attackTarget, hoverTarget: undefined })}
                                onClick={() => setAttackTarget({ ...attackTarget, clickTarget: x })}>
                                {x.userName}
                            </ListItem>
                        </React.Fragment>)
                    }
                </List>
                <Box display='flex' justifyContent='flex-end' sx={{ width: '100%' }}>
                    <Button sx={{ marginRight: 2 }} variant='contained' disabled={attackTarget.clickTarget === undefined}
                        onClick={() => { setAttackTarget({ clickTarget: undefined, hoverTarget: undefined }); handleModalClose(); handleAttack([attackTarget.clickTarget!]); }}>Ok</Button>
                    {hasSword ? undefined : <Button variant='contained' onClick={() => { setAttackTarget({ clickTarget: undefined, hoverTarget: undefined }); handleModalClose(); }}>Cancel</Button>}
                </Box>
            </Box>
    }

    const choiceConfirm = (playerChoice: PlayerChoice, text: string) => {
        return <Button fullWidth size='large' variant='contained' disabled={choiceTarget.clickTarget === undefined}
            onClick={() => {
                playerChoice.result = choiceTarget.clickTarget;
                setChoiceTarget({});
                handleModalClose();
                handleChoice(playerChoice);
            }}>
            {text}
        </Button>;
    }

    const choiceElements = (playerChoice: PlayerChoice) => {
        let hasImage = playerChoice.choice.type !== ChoiceType.counterattack && playerChoice.choice.type !== ChoiceType.move
            && playerChoice.choice.type !== ChoiceType.rerollMovement && playerChoice.choice.type !== ChoiceType.teleport
            && playerChoice.choice.type !== ChoiceType.area;
        return <Box sx={{ marginTop: 2, width: '100%', flexWrap: 'wrap', rowGap: 2 }} display='flex' justifyContent='space-between' alignItems='center'>
            {
                hasImage ? <Box component='img' sx={{ height: 360, maxWidth: '100%', objectFit: 'contain', marginX: { xs: 'auto', sm: 0 } }} alt={playerChoice.choice.card.name} src={`${import.meta.env.BASE_URL}assets/game/${playerChoice.choice.card.drawDeck}/${playerChoice.choice.card.name}.jpg`} /> : undefined}
            <Box display='flex' justifyContent='flex-end' flexDirection='column' sx={{ height: { xs: 'auto', sm: hasImage ? 340 : '100%' }, width: { xs: '100%', sm: hasImage ? 200 : '100%' }, maxWidth: '100%', gap: 2 }}>
                {(() => {
                    switch (playerChoice.choice.type) {
                        case ChoiceType.equipment: {
                            const isAltar = playerChoice.choice.card.name === 'Erstwhile Altar';
                            const isBanana = playerChoice.choice.card.name === 'Banana Peel';
                            const equipmentOwners = connection.gameState.lobby.playerList.filter(player =>
                                player.piece.items.length > 0
                                && (isAltar
                                    ? player.user.id !== playerChoice.playerId
                                    : player.user.id === playerChoice.choice.target));
                            return <React.Fragment>
                                <List disablePadding sx={{ backgroundColor: themeOptions.palette!.background!.paper!, width: '100%', overflowY: 'auto', overflowX: 'hidden', maxHeight: '200px', marginBottom: 2, marginTop: 2 }}>
                                    {
                                        equipmentOwners.map((x, i) => x.piece.items.map((y, j) => {
                                                const item = `${x.user.id},${y.name}`;

                                                return <React.Fragment key={`choice_target_${i}_${j}`}>
                                                    {i + j === 0 ? undefined : <Divider variant='fullWidth' component='li' />}
                                                    <ListItem sx={{
                                                        cursor: 'pointer',
                                                        color: item === choiceTarget.clickTarget ? 'white' : undefined,
                                                        backgroundColor: item === choiceTarget.clickTarget ? clickColor
                                                            : item === choiceTarget.hoverTarget ? hoverColor : undefined
                                                    }}
                                                        onMouseEnter={() => setChoiceTarget({ ...choiceTarget, hoverTarget: item })}
                                                        onMouseLeave={() => setChoiceTarget({ ...choiceTarget, hoverTarget: undefined })}
                                                        onClick={() => setChoiceTarget({ ...choiceTarget, clickTarget: item })}>
                                                        {`${x.user.userName} -> ${y.name}`}
                                                    </ListItem>
                                                </React.Fragment>
                                            }))
                                    }
                                </List>
                                {equipmentOwners.length > 0 ? choiceConfirm(playerChoice, isBanana ? 'Discard equipment' : 'Ok') : <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'skip';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>Skip</Button>}
                            </React.Fragment>;
                        }
                        case ChoiceType.hermitGreed: {
                            const target = connection.gameState.lobby.playerList.find(player => player.user.id === playerChoice.choice.target);
                            return <React.Fragment>
                                <List disablePadding sx={{ backgroundColor: themeOptions.palette!.background!.paper!, width: '100%', overflowY: 'auto', overflowX: 'hidden', maxHeight: '200px', marginBottom: 2, marginTop: 2 }}>
                                    {target?.piece.items.map(item => {
                                        const itemChoice = `${target.user.id},${item.name}`;
                                        return <ListItem key={itemChoice} sx={{
                                            cursor: 'pointer',
                                            color: itemChoice === choiceTarget.clickTarget ? 'white' : undefined,
                                            backgroundColor: itemChoice === choiceTarget.clickTarget ? clickColor
                                                : itemChoice === choiceTarget.hoverTarget ? hoverColor : undefined
                                        }}
                                            onMouseEnter={() => setChoiceTarget({ ...choiceTarget, hoverTarget: itemChoice })}
                                            onMouseLeave={() => setChoiceTarget({ ...choiceTarget, hoverTarget: undefined })}
                                            onClick={() => setChoiceTarget({ ...choiceTarget, clickTarget: itemChoice })}>
                                            {`Give ${item.name}`}
                                        </ListItem>;
                                    })}
                                </List>
                                {choiceConfirm(playerChoice, 'Give equipment')}
                                <Button fullWidth size='large' variant='contained' color='warning' onClick={() => {
                                    playerChoice.result = 'damage';
                                    setChoiceTarget({});
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>
                                    Take 1 damage
                                </Button>
                            </React.Fragment>;
                        }
                        case ChoiceType.hermitFaction:
                            return <React.Fragment>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'shadow';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>Resolve as Shadow</Button>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'hunter';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>Resolve as Hunter</Button>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'neutral';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>Resolve as Neutral</Button>
                            </React.Fragment>;
                        case ChoiceType.move: {
                            const rollResult = rollDice([4, 6]);
                            return <React.Fragment>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = playerChoice.choice.value;
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>
                                    {playerChoice.choice.value}
                                </Button>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = JSON.stringify(rollResult);
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>
                                    {rollResult[0] + rollResult[1]}
                                </Button>
                            </React.Fragment>
                        }
                        case ChoiceType.rerollMovement: {
                            const reroll = rollDice([6, 4]);
                            return <Button fullWidth size='large' variant='contained' onClick={() => {
                                playerChoice.result = JSON.stringify(reroll);
                                handleModalClose();
                                handleChoice(playerChoice);
                            }}>
                                Reroll movement ({reroll[0]} + {reroll[1]})
                            </Button>;
                        }
                        case ChoiceType.teleport: {
                            const position = connection.gameState.lobby.playerList.find(player => player.user.id === playerChoice.playerId)?.piece.position;
                            const areas = connection.gameState.lobby.decks.areas.cards;
                            const adjacentAreas = position === undefined || position < 0 ? [] : [
                                areas[(position - 1 + areas.length) % areas.length],
                                areas[(position + 1) % areas.length]
                            ].filter((area, index, all): area is NonNullable<typeof area> => Boolean(area) && all.findIndex(candidate => candidate?.name === area?.name) === index);
                            return <React.Fragment>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'normal';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>Move normally</Button>
                                {adjacentAreas.map(area => <Button key={area.name} fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = area.name;
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>Teleport to {area.name}</Button>)}
                            </React.Fragment>;
                        }
                        case ChoiceType.area:
                            return <React.Fragment>
                                <List disablePadding sx={{ backgroundColor: themeOptions.palette!.background!.paper!, width: '100%', overflowY: 'auto', overflowX: 'hidden', maxHeight: '200px', marginBottom: 2, marginTop: 2 }}>
                                    {connection.gameState.lobby.decks.areas.cards.map((area, index) => <React.Fragment key={`area_${area.name}`}>
                                        {index === 0 ? undefined : <Divider variant='fullWidth' component='li' />}
                                        <ListItem sx={{
                                            cursor: 'pointer',
                                            color: area.name === choiceTarget.clickTarget ? 'white' : undefined,
                                            backgroundColor: area.name === choiceTarget.clickTarget ? clickColor
                                                : area.name === choiceTarget.hoverTarget ? hoverColor : undefined
                                        }}
                                            onMouseEnter={() => setChoiceTarget({ ...choiceTarget, hoverTarget: area.name })}
                                            onMouseLeave={() => setChoiceTarget({ ...choiceTarget, hoverTarget: undefined })}
                                            onClick={() => setChoiceTarget({ ...choiceTarget, clickTarget: area.name })}>
                                            {area.name}
                                        </ListItem>
                                    </React.Fragment>)}
                                </List>
                                {choiceConfirm(playerChoice, 'Ok')}
                            </React.Fragment>;
                        case ChoiceType.reveal:
                            return <React.Fragment>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'yes';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>
                                    Yes
                                </Button>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'no';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>
                                    No
                                </Button>
                            </React.Fragment>
                        case ChoiceType.target: {
                            const isHermitCard = playerChoice.choice.card.name.startsWith("Hermit's ");
                            const targets = connection.gameState.lobby.playerList.filter(x =>
                                (!x.piece.dead || (playerChoice.choice.card.name === 'Blessing' && x.user.id === playerChoice.choice.target))
                                && (!isHermitCard || x.user.id !== playerChoice.playerId));
                            if (targets.length === 0) {
                                return <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'skip';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>Skip</Button>;
                            }
                            return <React.Fragment>
                                <List disablePadding sx={{ backgroundColor: themeOptions.palette!.background!.paper!, width: '100%', overflowY: 'auto', overflowX: 'hidden', maxHeight: '200px', marginBottom: 2, marginTop: 2 }}>
                                    {
                                        targets.map((x, i) => <React.Fragment key={`choice_target_${i}`}>
                                            {i === 0 ? undefined : <Divider variant='fullWidth' component='li' />}
                                            <ListItem sx={{
                                                cursor: 'pointer',
                                                color: x.user.id === choiceTarget.clickTarget ? 'white' : undefined,
                                                backgroundColor: x.user.id === choiceTarget.clickTarget ? clickColor
                                                    : x.user.id === choiceTarget.hoverTarget ? hoverColor : undefined
                                            }}
                                                onMouseEnter={() => setChoiceTarget({ ...choiceTarget, hoverTarget: x.user.id })}
                                                onMouseLeave={() => setChoiceTarget({ ...choiceTarget, hoverTarget: undefined })}
                                                onClick={() => setChoiceTarget({ ...choiceTarget, clickTarget: x.user.id })}>
                                                {x.user.userName}
                                            </ListItem>
                                        </React.Fragment>)
                                    }
                                </List>
                                {choiceConfirm(playerChoice, 'Ok')}
                            </React.Fragment>
                        }
                        case ChoiceType.weirdWoods: {
                            const target = connection.gameState.lobby.playerList.find(player => player.user.id === playerChoice.choice.target);
                            return <React.Fragment>
                                <Typography>Choose an effect for {target?.user.userName ?? 'the targeted player'}.</Typography>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'damage';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>Deal 2 Damage</Button>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'heal';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>Heal 1 Damage</Button>
                            </React.Fragment>;
                        }
                        case ChoiceType.counterattack: {
                            const attacker = connection.gameState.lobby.playerList.find(player => player.user.id === playerChoice.choice.target);
                            return <React.Fragment>
                                <Typography>Counterattack {attacker?.user.userName ?? 'the attacker'}?</Typography>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    handleModalClose();
                                    handleAttack(attacker ? [attacker.user] : []);
                                }}>Counterattack</Button>
                                <Button fullWidth size='large' variant='contained' onClick={() => {
                                    playerChoice.result = 'skip';
                                    handleModalClose();
                                    handleChoice(playerChoice);
                                }}>Skip</Button>
                            </React.Fragment>;
                        }
                        case ChoiceType.draw:
                            return <React.Fragment>
                                <List disablePadding sx={{ backgroundColor: themeOptions.palette!.background!.paper!, width: '100%', overflowY: 'auto', overflowX: 'hidden', maxHeight: '200px', marginBottom: 2, marginTop: 2 }}>
                                    <ListItem sx={{
                                        cursor: 'pointer',
                                        color: 'green' === choiceTarget.clickTarget ? 'white' : undefined,
                                        backgroundColor: 'green' === choiceTarget.clickTarget ? clickColor
                                            : 'green' === choiceTarget.hoverTarget ? hoverColor : undefined
                                    }}
                                        onMouseEnter={() => setChoiceTarget({ ...choiceTarget, hoverTarget: 'green' })}
                                        onMouseLeave={() => setChoiceTarget({ ...choiceTarget, hoverTarget: undefined })}
                                        onClick={() => setChoiceTarget({ ...choiceTarget, clickTarget: 'green' })}>
                                        Hermit
                                    </ListItem>
                                    <Divider variant='fullWidth' component='li' />
                                    <ListItem sx={{
                                        cursor: 'pointer',
                                        backgroundColor: 'white' === choiceTarget.clickTarget ? clickColor
                                            : 'white' === choiceTarget.hoverTarget ? hoverColor : undefined
                                    }}
                                        onMouseEnter={() => setChoiceTarget({ ...choiceTarget, hoverTarget: 'white' })}
                                        onMouseLeave={() => setChoiceTarget({ ...choiceTarget, hoverTarget: undefined })}
                                        onClick={() => setChoiceTarget({ ...choiceTarget, clickTarget: 'white' })}>
                                        White
                                    </ListItem>
                                    <Divider variant='fullWidth' component='li' />
                                    <ListItem sx={{
                                        cursor: 'pointer',
                                        color: 'black' === choiceTarget.clickTarget ? 'white' : undefined,
                                        backgroundColor: 'black' === choiceTarget.clickTarget ? clickColor
                                            : 'black' === choiceTarget.hoverTarget ? hoverColor : undefined
                                    }}
                                        onMouseEnter={() => setChoiceTarget({ ...choiceTarget, hoverTarget: 'black' })}
                                        onMouseLeave={() => setChoiceTarget({ ...choiceTarget, hoverTarget: undefined })}
                                        onClick={() => setChoiceTarget({ ...choiceTarget, clickTarget: 'black' })}>
                                        Black
                                    </ListItem>
                                </List>
                                {choiceConfirm(playerChoice, 'Ok')}
                            </React.Fragment>
                        default:
                            return choiceConfirm(playerChoice, 'Ok');
                    }
                })()}
            </Box>
        </Box >
    }

    return <Dialog open={modalState.openModal}>
        <Box display='flex' flexDirection='column' justifyContent='space-between' alignItems='center' width={500} p={2} sx={{ maxWidth: '100%', boxSizing: 'border-box', overflow: 'hidden' }}>
            {
                modalState.modalMessage ? <Box sx={{
                    width: 'calc(100% + 32px)', paddingTop: '8px', paddingLeft: '16px',
                    marginX: '-16px', marginTop: '-16px', backgroundColor: themeOptions.palette!.background!.default!
                }}>
                    <Typography variant='h5' sx={{ width: '100%' }}>{modalState.modalMessage}</Typography>
                </Box> : undefined
            }
            {
                modalState.targets ? attackElement(modalState.targets, modalState.hasSword!) : undefined
            }
            {
                modalState.playerChoice ? choiceElements(modalState.playerChoice) : undefined
            }
        </Box>
    </Dialog>
};
