import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import { DisconnectedPlayer } from '../helpers/common';

interface DisconnectDialogProps {
    disconnectedPlayer?: DisconnectedPlayer,
    isHost: boolean,
    onQuit: () => void,
    onReplaceWithBot: () => void,
    onEndGame: () => void
}

export default function DisconnectDialog({ disconnectedPlayer, isHost, onQuit, onReplaceWithBot, onEndGame }: DisconnectDialogProps) {
    if (!disconnectedPlayer) return undefined;
    const subject = disconnectedPlayer.isHost ? 'The host' : disconnectedPlayer.playerName;

    return <Dialog open aria-labelledby='disconnect-dialog-title'>
        <DialogTitle id='disconnect-dialog-title'>Game Paused</DialogTitle>
        <DialogContent>
            <Typography>{subject} disconnected. The game is paused for all players.</Typography>
            {disconnectedPlayer.isHost && !isHost
                ? <Typography sx={{ marginTop: 1 }}>Attempting to reconnect to the host automatically.</Typography>
                : undefined}
        </DialogContent>
        <DialogActions>
            <Button onClick={onQuit} variant='contained'>Quit</Button>
            {isHost && !disconnectedPlayer.isHost ? <>
                <Button onClick={onReplaceWithBot} variant='contained'>Replace with Bot</Button>
                <Button onClick={onEndGame} variant='contained' color='error'>End Game</Button>
            </> : undefined}
        </DialogActions>
    </Dialog>;
}
