import * as React from 'react';
import { useAppSelector } from '../store/hooks';
import Box from '@mui/material/Box';
import Divider from '@mui/material/Divider';
import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemText from '@mui/material/ListItemText';
import { LogEntry, ConnectionState, CardModalState } from '../helpers/common';
import Typography from '@mui/material/Typography';
import Button from '@mui/material/Button';
import { isTestMode } from '../store';
import { themeOptions } from '../helpers/theme';
import { GiNotebook } from 'react-icons/gi';
import ListItemAvatar from '@mui/material/ListItemAvatar';
import Dialog from '@mui/material/Dialog';
import Card from '@mui/material/Card';
import Grid from '@mui/material/Grid';


function LogList({ noText = false }: { noText?: boolean }) {
    const connection = useAppSelector((state) => state.connection) as ConnectionState;
    const [showLog, setShowLog] = React.useState<boolean>(false);
    const grayBackground = 'rgba(25, 34, 49, .5)';
    const [modalState, setModal] = React.useState<CardModalState>({ openModal: false, src: '', alt: '' });
    const contentScale = noText ? 1.5 : 1;

    return <Grid sx={{ marginTop: { xs: 1, md: isTestMode ? 30 : 0 }, position: 'absolute', zIndex: 1200, paddingTop: { xs: 0, md: isTestMode ? 5 : 2 }, paddingX: { xs: '12px', md: 2 }, width: '100%', alignItems: 'flex-end', flexDirection: 'column', display: 'flex',  pointerEvents: 'none' }}>
        {
            noText ?
                <Button aria-label='Log' sx={{ minHeight: '54px', minWidth: '54px', width: '54px', padding: 0, marginBottom: 1, fontSize: '1.3125rem', pointerEvents: 'auto' }} variant='contained' onClick={() => setShowLog(!showLog)}>
                    <GiNotebook />
                </Button> :
                <Button sx={{ minHeight: '54px', paddingX: 3, fontSize: '1.3125rem', pointerEvents: 'auto' }} variant='contained' onClick={() => setShowLog(!showLog)}>
                    <GiNotebook style={{ marginRight: 16, marginTop: '-4px' }} /> Log
                </Button>
        }
        {
            showLog ?
                <Card variant='outlined' sx={{ backgroundColor: themeOptions.palette!.background!.default!, width: { xs: '100%', md: '500px' }, height: { xs: '400px', md: '300px' } }}>
                    <Typography sx={{ marginLeft: 2, fontSize: `${1.5 * contentScale}rem` }} variant='h5'>Log</Typography>
                    <Divider />
                    <List disablePadding sx={{ overflowY: 'auto', overflowX: 'hidden', minHeight: '100%', maxHeight: '100%', paddingX: 1, backgroundColor: themeOptions.palette!.background!.paper! }}>
                        {
                            connection.gameState.lobby.gameLog.map((x: LogEntry, i: number) =>
                                <ListItem sx={{ backgroundColor: grayBackground, borderRadius: '8px', marginBottom: 1 }} key={`log_item_${i}`}>
                                    <ListItemText disableTypography
                                        primary={
                                            <Box>
                                                <Typography variant='body1' sx={{ fontSize: `${contentScale}rem` }}>{x.userName}</Typography>
                                                <Divider sx={{ marginBottom: 1 }} />
                                            </Box>
                                        }
                                        secondary={<Typography variant='body2' sx={{ fontSize: `${0.875 * contentScale}rem` }}>{x.text}</Typography>}
                                    />
                                    {
                                        x.info.includes('/') ?
                                            <ListItemAvatar sx={{ cursor: 'zoom-in' }} onClick={() => setModal({ src: `${import.meta.env.BASE_URL}assets/game/${x.info}.jpg`, alt: x.info, openModal: true })}>
                                                <Box sx={{ float: 'right' }} component='img' alt={x.info} width={35 * contentScale} height={50 * contentScale} src={`${import.meta.env.BASE_URL}assets/game/${x.info}.jpg`} />
                                            </ListItemAvatar> : undefined
                                    }
                                </ListItem>
                            )
                        }
                    </List>
                </Card> : undefined
        }
        <Dialog
            open={modalState.openModal}
            onClose={() => setModal({ openModal: false, alt: '', src: '' })}
        >
            {modalState.src && (<Box component='img' height={600} src={modalState.src} alt={modalState.alt} />)}
        </Dialog>
    </Grid >;
}

export default LogList;
