import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import { Card, ModalState, PlayerActionType, PlayerAttack, PlayerEvent, PlayerMove } from '../helpers/common';
import React, { useEffect } from 'react';
import { themeOptions } from '../helpers/theme';
import DiceBox from '@3d-dice/dice-box-threejs';
import Dialog from '@mui/material/Dialog';
import LinearProgress from '@mui/material/LinearProgress';
import Button from '@mui/material/Button';
import { EVENT_AUTO_DISMISS_MS } from '../helpers/eventConfig';

export default function EventDialog({ playerEvent, modalState, handleModalClose = () => { }, revealedCard, card }:
    {
        playerEvent: PlayerEvent,
        modalState: ModalState,
        handleModalClose: () => void,
        revealedCard?: Card,
        card?: Card
    }) {

    const shownCard = revealedCard ?? card;
    const requiresCardAcknowledgement = Boolean(revealedCard);

    function drawDice(playerEvent: PlayerEvent, finish: () => void): boolean {
        if (typeof WebGLRenderingContext === 'undefined') return false;
        const container = document.querySelector('#scene-container');
        // Wait for layout before constructing DiceBox. This also lets the
        // queue advance immediately in non-WebGL environments.
        if (!container || container.clientWidth === 0 || container.clientHeight === 0) return false;
        try {
            const dBox = new DiceBox('#scene-container', { onRollComplete: finish });
            void dBox.initialize().then(() => {
                const roll = playerEvent.actionType === PlayerActionType.playerMove
                    ? (playerEvent as PlayerMove).moveRoll
                    : (playerEvent as PlayerAttack).damageRoll;
                return dBox.roll(roll?.length === 1 ? `1d4@${roll[0]}` : roll ? `1d6@${roll[0]},1d4@${roll[1]}` : '1d6,1d4');
            }).then(finish).catch(finish);
            return true;
        } catch {
            return false;
        }
    }

    useEffect(() => {
        if (requiresCardAcknowledgement) return;
        let finished = false;
        let completionTimer: number | undefined;
        const finish = () => {
            if (finished) return;
            finished = true;
            handleModalClose();
        };
        // Dialog content is portalled; let it attach before DiceBox queries
        // the scene container.
        const startTimer = window.setTimeout(() => {
            const hasDice = playerEvent.animateDice !== false
                && (playerEvent.actionType === PlayerActionType.playerMove || playerEvent.actionType === PlayerActionType.playerAttack);
            const diceStarted = hasDice && drawDice(playerEvent, finish);
            if (!diceStarted) {
                completionTimer = window.setTimeout(finish, hasDice ? 0 : EVENT_AUTO_DISMISS_MS);
            }
        }, 0);
        return () => {
            window.clearTimeout(startTimer);
            if (completionTimer !== undefined) window.clearTimeout(completionTimer);
        };
    }, [playerEvent, handleModalClose, requiresCardAcknowledgement]);

    const eventElements = () => {
        if (shownCard) {
            return <React.Fragment>
                <Box component='img' sx={{ height: 360, maxWidth: '100%', objectFit: 'contain', marginTop: 2, marginX: 'auto' }}
                    alt={shownCard.name} src={`${import.meta.env.BASE_URL}assets/game/${shownCard.drawDeck}/${shownCard.name}.jpg`} />
                {requiresCardAcknowledgement
                    ? <Button variant='contained' fullWidth sx={{ marginTop: 2 }} onClick={handleModalClose}>Ok</Button>
                    : undefined}
            </React.Fragment>;
        }
        if (playerEvent.animateDice === false) {
            return <LinearProgress sx={{ width: '100%', height: '5px', marginTop: 2, marginX: ' -16px' }} aria-label="Loading…" />;
        }
        switch (playerEvent.actionType) {
            case PlayerActionType.playerAttack:
            case PlayerActionType.playerMove:
                return <Box id='scene-container' sx={{ width: '100%', maxWidth: 460, height: 240 }} />;
            default:
                return <LinearProgress sx={{ width: '100%', height: '5px', marginTop: 2, marginX: ' -16px' }} aria-label="Loading…" />;
        }
    }

    if (!modalState.openModal) return undefined;
    return <Dialog open={modalState.openModal}>
        <Box role='status' display='flex' flexDirection='column' justifyContent='space-between' alignItems='center' width={500} p={2}
            sx={{ maxWidth: '100%', boxSizing: 'border-box', overflow: 'hidden' }}>
            {
                modalState.modalMessage ? <Box sx={{
                    width: 'calc(100% + 32px)', paddingTop: '8px', paddingLeft: '16px',
                    marginX: '-16px', marginTop: '-16px', backgroundColor: themeOptions.palette!.background!.default!
                }}>
                    <Typography variant='h5' sx={{ width: '100%' }}>{modalState.modalMessage}</Typography>
                </Box> : undefined
            }
            {eventElements()}
        </Box>
    </Dialog>;
};
